void Editor::selectBrushLibraryItem(const std::string& id,bool ctrl,bool shift){if(pending_!=Pending::None||document.active())return;const auto old=fillLibrarySelection_;const auto oldId=pencilImageBrushId_;const auto oldBrush=pencilImageBrush_;try{PatternBrushLibrary library(fillBrushLibraryDirectory());std::vector<std::string> ordered;for(const auto& item:library.list().brushes)if(item.folderId==fillFolder_)ordered.push_back(item.id);if(fillFolder_.empty())for(const auto& item:document.projectBrushes())ordered.push_back("project:"+item.metadata.id);if(std::find(ordered.begin(),ordered.end(),id)==ordered.end())throw std::runtime_error("Brush is not in current folder");fillLibrarySelection_.select(ordered,id,ctrl,shift);applyFillLibrarySelection();pencilImageBrushId_=fillLibrarySelection_.active;pencilImageBrush_.reset();if(!pencilImageBrushId_.empty()){resolvePencilImageBrush();if(pencilImageBrushId_.empty())throw std::runtime_error("Selected brush could not be loaded");}status_=fillLibrarySelection_.ids.empty()?U"已停用图像笔刷":U"已选择图案："+fillImageName_;}catch(const std::exception& e){fillLibrarySelection_=old;pencilImageBrushId_=oldId;pencilImageBrush_=oldBrush;try{applyFillLibrarySelection();}catch(...){}status_=U"图案选择失败："+unicodeText(e.what());}refresh();}
